import importlib.util,unittest,json,base64
from pathlib import Path
s=importlib.util.spec_from_file_location('prior',Path(__file__).with_name('qa-consolidated.py'));base=importlib.util.module_from_spec(s);s.loader.exec_module(base)
OUT=Path('docs/shared-recruiting-20261115/after');OUT.mkdir(parents=True,exist_ok=True)
class SharedRecruiting(base.Consolidated):
 def setUp(self):super().setUp();self.page.set_default_timeout(15000)
 def shot(self,name,selector=None):
  p=self.page;p.evaluate('async()=>{await document.fonts.ready;document.activeElement?.blur();document.querySelectorAll("img").forEach(i=>i.loading="eager");await Promise.all([...document.images].map(i=>i.decode().catch(()=>{})));}');p.wait_for_function('()=>!document.querySelector("[data-portrait-pending=true]")');p.evaluate('scrollTo(0,0)');self.assertEqual(p.locator('img').evaluate_all('(xs)=>xs.filter(i=>!i.complete||!i.naturalWidth).map(i=>i.alt)'),[])
  path=str(OUT/(base.base.ENGINE+'-'+name+'.png'))
  if selector:p.screenshot(path=path,full_page=True,clip=p.locator(selector).bounding_box())
  else:p.screenshot(path=path)
 def settled(self):
  self.page.wait_for_function('()=>document.querySelector("#recruiting-profile-builder .recruiting-imported [data-portrait-ready]")&&document.querySelector("#profile-summary .profile-avatar canvas")&&!document.querySelector("[data-portrait-pending=true]")')
 def stage(self,n):self.page.get_by_role('navigation',name='Recruiting journey',exact=True).locator('[data-stage="'+str(n)+'"]').click()
 def include(self,labels):
  for label in labels:self.page.get_by_label('Include '+label,exact=True).check()
