    self.nav('Media');p.get_by_role('button',name='Add Media',exact=True).click();p.locator('#media-upload').set_input_files('test/fixtures/qa-family-video.mp4');p.locator('#media-caption').fill('Synthetic '+sport+' selected highlight');p.locator('#media-event').select_option(event);p.get_by_role('button',name='Save media',exact=True).click();p.wait_for_selector('.family-media-gallery video')
    self.nav('Profile');p.get_by_text('About My Sport · Positions and Goals',exact=True).click();p.locator('#athlete-age').fill('16');p.locator('#athlete-about').fill('Existing '+sport+' athlete introduction');p.get_by_role('button',name='Save details',exact=True).click();p.wait_for_selector('#show-tryouts')
    if sport=='swimming':
     p.locator('#swimming-progress summary').click();p.locator('#target-discipline').fill('100 free');p.locator('#target-course').select_option('SCY');p.locator('#target-time').fill('1:18.00');p.get_by_role('button',name='Save target',exact=True).click();p.wait_for_function('()=>JSON.parse(localStorage.getItem("arenaPathway.v2")).profiles[0].swimmingTargets.length===1')
    p.goto(base.base.BASE+'/recruiting?athlete='+athlete);p.wait_for_selector('#recruiting-profile-builder',state='attached');school=p.locator('.research-results .research-card').first;schoolName=school.locator('h3').inner_text();schoolId=school.locator('[data-save]').get_attribute('data-save');school.locator('[data-save]').click();p.wait_for_function('(id)=>JSON.parse(localStorage.getItem("arenaPathway.v2")).profiles[0].saved.includes(id)',arg=schoolId);school.locator('.program-coaches summary').click();self.assertIn('No verified '+sport+' coaching contacts',school.inner_text());self.shot(sport+'-schools');self.stage(2);self.assertEqual(p.locator('[data-selection]:checked').count(),0);p.locator('#recruiting-rules').check();p.get_by_text('Edit athlete and academic information',exact=True).click();self.assertEqual(p.get_by_label('About Me / player overview',exact=True).input_value(),'Existing '+sport+' athlete introduction');p.get_by_label('High school',exact=True).fill('Synthetic Shared QA High School');p.get_by_label('Graduation year',exact=True).fill('2028');p.get_by_label('Academic details (optional; family-reported)',exact=True).fill('Family-reported academic description');p.get_by_label('GPA (optional; family-reported)',exact=True).fill('3.8');p.get_by_label('GPA scale',exact=True).fill('4');p.get_by_label('GPA type',exact=True).select_option('unweighted');p.get_by_label('Intended major (optional)',exact=True).fill('Engineering');p.get_by_label('College goals / recruiting interests',exact=True).fill('Synthetic academic and athletic aspirations');p.get_by_label('Personal achievements (one per line)',exact=True).fill('Synthetic selected personal honor\nSynthetic private honor');p.get_by_role('button',name='Save athlete information',exact=True).click();self.settled()
